table = {"AUG": "M", "GCU": "A", "GAA": "E", "UAA": "*"}
rna = "AUGGCUGAAUAA"
protein = ""
for i in range(0, len(rna) - 2, 3):
    aa = table[rna[i:i+3]]
    if aa == "*":
        break
    protein += aa
print(protein)

